query:
mutation CreateNoteTargets($data: [NoteTargetCreateInput!]!, $upsert: Boolean) {
  createNoteTargets(data: $data, upsert: $upsert) {
    __typename
    createdAt
    createdBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
    deletedAt
    id
    note {
      __typename
      id
      title
    }
    noteId
    position
    targetCompany {
      __typename
      domainName {
        primaryLinkUrl
        primaryLinkLabel
        secondaryLinks {
          label
          url
          __typename
        }
        __typename
      }
      id
      name
    }
    targetCompanyId
    targetOpportunity {
      __typename
      id
      name
    }
    targetOpportunityId
    targetPerson {
      __typename
      avatarFile {
        fileId
        label
        extension
        url
        __typename
      }
      id
      name {
        firstName
        lastName
        __typename
      }
    }
    targetPersonId
    updatedAt
    updatedBy {
      source
      workspaceMemberId
      name
      context {
        provider
        applicationId
        __typename
      }
      __typename
    }
  }
}
